import '@servicenow/sdk/global'
import { action, Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for DEF0774889: __action_status__.code and __action_status__.message datapills
 * Tests nested action status datapills used in template strings in action inputs
 */
Flow(
    {
        $id: Now.ID['fcb8d23f48613210f8773d02981a82e2'],
        name: 'Test flow with action_satus datapill',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['8eb8563f48613210f8773d02981a82f0'],
        },
        {
            condition: '^EQ',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
            table: 'incident',
        }
    ),
    (_params) => {
        // First action - we'll reference its __action_status__ outputs
        const actionInstance_1 = wfa.action(
            action.core.log,
            {
                $id: Now.ID['e9c81a3f48613210f8773d02981a82b1'],
                uuid: '42c8c2b8-8c56-41dd-b51f-d082c5b77772',
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(_params.trigger.table_name, 'string'),
            }
        )

        // Second action uses __action_status__.code and __action_status__.message in a template string
        // This should generate: {{uuid.__action_status__.code}}{{uuid.__action_status__.message}}
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['8cd89a3f48613210f8773d02981a826b'],
                uuid: 'b420944c-af9b-4330-b5e6-af88e8599eba',
            },
            {
                log_level: 'info',
                log_message: `${wfa.dataPill(actionInstance_1.__action_status__.code, 'integer')}${wfa.dataPill(actionInstance_1.__action_status__.message, 'string')}`,
            }
        )
    }
)
